{"command":"cat > build/bench_par.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

#define NTHREADS 6

typedef struct {
    const unsigned char *key;
    const unsigned char *nonce;
    const unsigned char *pt;
    unsigned char *ct;
    size_t offset;
    size_t len;
    unsigned int counter; /* block counter */
    unsigned char block_out[64]; /* first partial keystream if offset not aligned - not used if aligned */
} job_t;

/* Encrypt a range of plaintext that is 64-byte aligned in offset, length multiple of 64
   (except possibly the last chunk). Uses ChaCha20 via EVP_chacha20.
   OpenSSL ChaCha20 IV is 16 bytes: 4 byte counter (little endian) + 12 byte nonce.
*/
static void chacha_crypt(const unsigned char *key, const unsigned char *nonce12,
                         unsigned int counter, const unsigned char *in, unsigned char *out, size_t len) {
    unsigned char iv[16];
    iv[0] = (unsigned char)(counter & 0xff);
    iv[1] = (unsigned char)((counter >> 8) & 0xff);
    iv[2] = (unsigned char)((counter >> 16) & 0xff);
    iv[3] = (unsigned char)((counter >> 24) & 0xff);
    memcpy(iv + 4, nonce12, 12);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outl = 0, tmplen = 0;
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, key, iv);
    /* process in chunks if len > INT_MAX, here len is fine */
    size_t done = 0;
    while (done < len) {
        int chunk = (int)((len - done) > 1<<30 ? 1<<30 : (len - done));
        EVP_EncryptUpdate(ctx, out + done, &outl, in + done, chunk);
        done += outl;
    }
    EVP_EncryptFinal_ex(ctx, out + done, &tmplen);
    EVP_CIPHER_CTX_free(ctx);
}

typedef struct {
    const unsigned char *key;
    const unsigned char *nonce;
    const unsigned char *pt;
    unsigned char *ct;
    size_t offset;
    size_t len;
    unsigned int counter;
} tjob;

static void *worker(void *arg) {
    tjob *j = arg;
    chacha_crypt(j->key, j->nonce, j->counter, j->pt + j->offset, j->ct + j->offset, j->len);
    return NULL;
}

int main() {
    size_t n = 40000ull * 1024ull;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    unsigned char *ct2 = malloc(n);
    unsigned char key[32], nonce[12];
    memset(pt, 0x5a, n);
    memset(key, 0x11, 32);
    memset(nonce, 0x22, 12);

    /* single thread baseline via chacha20 */
    double t0 = now();
    chacha_crypt(key, nonce, 1, pt, ct, n); /* RFC counter starts at 1 for poly1305? for raw chacha often 0 */
    double t1 = now();
    printf("single chacha counter=1: %.4f s\n", t1-t0);

    /* parallel */
    int nth = NTHREADS;
    pthread_t th[16];
    tjob jobs[16];
    size_t block = 64;
    size_t chunk = (n / nth) & ~(block - 1);
    t0 = now();
    int reps = 3;
    for (int r = 0; r < reps; r++) {
        size_t off = 0;
        for (int i = 0; i < nth; i++) {
            size_t len = (i == nth - 1) ? (n - off) : chunk;
            jobs[i].key = key;
            jobs[i].nonce = nonce;
            jobs[i].pt = pt;
            jobs[i].ct = ct2;
            jobs[i].offset = off;
            jobs[i].len = len;
            jobs[i].counter = 1 + (unsigned int)(off / 64);
            pthread_create(&th[i], NULL, worker, &jobs[i]);
            off += len;
        }
        for (int i = 0; i < nth; i++) pthread_join(th[i], NULL);
    }
    t1 = now();
    printf("parallel %d: %.4f s/op  match=%d\n", nth, (t1-t0)/reps, memcmp(ct, ct2, n)==0);

    /* try 12 threads */
    nth = 12;
    t0 = now();
    for (int r = 0; r < reps; r++) {
        size_t off = 0;
        chunk = (n / nth) & ~(block - 1);
        for (int i = 0; i < nth; i++) {
            size_t len = (i == nth - 1) ? (n - off) : chunk;
            jobs[i].key = key;
            jobs[i].nonce = nonce;
            jobs[i].pt = pt;
            jobs[i].ct = ct2;
            jobs[i].offset = off;
            jobs[i].len = len;
            jobs[i].counter = 1 + (unsigned int)(off / 64);
            pthread_create(&th[i], NULL, worker, &jobs[i]);
            off += len;
        }
        for (int i = 0; i < nth; i++) pthread_join(th[i], NULL);
    }
    t1 = now();
    printf("parallel %d: %.4f s/op  match=%d\n", nth, (t1-t0)/reps, memcmp(ct, ct2, n)==0);
    return 0;
}
EOF
