{"command":"mkdir -p build && cat > build/bench_go.go << 'EOF'
package main

import (
	"crypto/cipher"
	"fmt"
	"time"
	"golang.org/x/crypto/chacha20poly1305"
)

func main() {
	n := 40000 * 1024
	key := make([]byte, 32)
	nonce := make([]byte, 12)
	pt := make([]byte, n)
	aad := make([]byte, 32)
	for i := range key {
		key[i] = byte(i)
	}
	for i := range pt {
		pt[i] = byte(i)
	}
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		panic(err)
	}
	var ciph cipher.AEAD = aead
	out := ciph.Seal(nil, nonce, pt, aad)
	fmt.Println("out", len(out))
	t0 := time.Now()
	reps := 5
	for i := 0; i < reps; i++ {
		out = ciph.Seal(out[:0], nonce, pt, aad)
	}
	dt := time.Since(t0)
	fmt.Printf("go seal: %.4f s/op\n", dt.Seconds()/float64(reps))

	// no aad
	t0 = time.Now()
	for i := 0; i < reps; i++ {
		out = ciph.Seal(out[:0], nonce, pt, nil)
	}
	dt = time.Since(t0)
	fmt.Printf("go seal no aad: %.4f s/op\n", dt.Seconds()/float64(reps))
}
EOF
