#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <openssl/evp.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 40000ull * 1024ull;
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *ct = aligned_alloc(64, n);
    unsigned char *ct2 = aligned_alloc(64, n);
    memset(pt, 0x5a, n);
    unsigned int key[8];
    for (int i = 0; i < 8; i++) key[i] = 0x11111111u * (i+1);
    unsigned char nonce[12];
    memset(nonce, 0x22, 12);

    /* OpenSSL ChaCha20 IV layout: counter is LE 32-bit at start of 16-byte IV, then nonce.
       ChaCha20_ctr32 counter argument: typically 4 uint32: counter, nonce0, nonce1, nonce2
       Let's verify against EVP.
    */
    unsigned char iv[16];
    memset(iv, 0, 16);
    iv[0] = 1; /* counter = 1 */
    memcpy(iv+4, nonce, 12);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outl=0, tmplen=0;
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, (unsigned char*)key, iv);
    EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)n);
    EVP_EncryptFinal_ex(ctx, ct+outl, &tmplen);
    EVP_CIPHER_CTX_free(ctx);

    unsigned int counter[4];
    counter[0] = 1;
    memcpy(&counter[1], nonce, 12);

    double t0 = now();
    int reps = 3;
    for (int i = 0; i < reps; i++) {
        ChaCha20_ctr32(ct2, pt, n, key, counter);
    }
    double t1 = now();
    printf("ChaCha20_ctr32: %.4f s/op match=%d first mismatch search...\n", (t1-t0)/reps, memcmp(ct, ct2, n)==0);
    if (memcmp(ct, ct2, n) != 0) {
        for (size_t i = 0; i < n; i++) if (ct[i]!=ct2[i]) { printf("mismatch at %zu evp=%02x raw=%02x\n", i, ct[i], ct2[i]); break; }
        /* try counter 0 */
        counter[0] = 0;
        ChaCha20_ctr32(ct2, pt, 64, key, counter);
        printf("counter0 match first block %d\n", memcmp(ct, ct2, 64)==0);
        /* maybe key is byte-swapped? key was passed as bytes to EVP from uint32 memory, same LE. */
        /* try nonce in counter differently */
    } else {
        printf("MATCH counter layout OK\n");
    }
    return 0;
}
EOF
