    memset(key, 0x11, 32);
    void *ctx = malloc(Poly1305_ctx_size());
    Poly1305_Init(ctx, key);
    double t0 = now();
    int reps = 3;
    for (int i = 0; i < reps; i++) {
        Poly1305_Init(ctx, key);
        Poly1305_Update(ctx, pt, n);
        unsigned char mac[16];
        Poly1305_Final(ctx, mac);
    }
    double t1 = now();
    printf("poly1305 40MB: %.4f s/op\n", (t1-t0)/reps);

    unsigned int k[8];
    memset(k, 0x22, sizeof k);
    unsigned int counter[4] = {1, 0x01020304, 0x05060708, 0x090a0b0c};
    t0 = now();
    for (int i = 0; i < reps; i++) {
        ChaCha20_ctr32(ct, pt, n, k, counter);
    }
    t1 = now();
    printf("chacha 40MB: %.4f s/op\n", (t1-t0)/reps);

    /* parallel chacha with persistent threads via a simple barrier? just spawn */
    return 0;
}
