{"command":"cat > build/bench_pool.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <openssl/evp.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);
size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

#define NTH 12

typedef struct {
    pthread_t th;
    pthread_mutex_t mu;
    pthread_cond_t cv;
    pthread_cond_t done_cv;
    int job; /* 0 idle wait, 1 work, 2 exit */
    int finished;
    const unsigned char *in;
    unsigned char *out;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
} worker_t;

static worker_t workers[NTH];

static void *worker_fn(void *arg) {
    worker_t *w = arg;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (w->job == 0) pthread_cond_wait(&w->cv, &w->mu);
        if (w->job == 2) { pthread_mutex_unlock(&w->mu); return NULL; }
        pthread_mutex_unlock(&w->mu);
        ChaCha20_ctr32(w->out, w->in, w->len, w->key, w->counter);
        pthread_mutex_lock(&w->mu);
        w->job = 0;
        w->finished = 1;
        pthread_cond_signal(&w->done_cv);
    }
}

static void pool_init(void) {
    for (int i = 0; i < NTH; i++) {
        pthread_mutex_init(&workers[i].mu, NULL);
        pthread_cond_init(&workers[i].cv, NULL);
        pthread_cond_init(&workers[i].done_cv, NULL);
        workers[i].job = 0;
        workers[i].finished = 0;
        pthread_create(&workers[i].th, NULL, worker_fn, &workers[i]);
    }
}

static void pool_crypt(const unsigned int key[8], const unsigned int counter_base[4],
                       const unsigned char *in, unsigned char *out, size_t n) {
    size_t chunk = (n / NTH) & ~63ull;
    size_t off = 0;
    for (int i = 0; i < NTH; i++) {
        size_t len = (i == NTH-1) ? (n - off) : chunk;
        worker_t *w = &workers[i];
        pthread_mutex_lock(&w->mu);
        memcpy(w->key, key, 32);
        memcpy(w->counter, counter_base, 16);
        w->counter[0] = counter_base[0] + (unsigned int)(off / 64);
        w->in = in + off;
        w->out = out + off;
        w->len = len;
        w->finished = 0;
        w->job = 1;
        pthread_cond_signal(&w->cv);
        pthread_mutex_unlock(&w->mu);
        off += len;
    }
    for (int i = 0; i < NTH; i++) {
        worker_t *w = &workers[i];
        pthread_mutex_lock(&w->mu);
        while (!w->finished) pthread_cond_wait(&w->done_cv, &w->mu);
        pthread_mutex_unlock(&w->mu);
    }
}

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

/* RFC 8439 ChaCha20-Poly1305 encrypt */
static void aead_encrypt(const unsigned char key[32], const unsigned char nonce[12],
                         const unsigned char *aad, size_t aad_len,
                         const unsigned char *pt, unsigned char *ct, size_t n,
                         unsigned char tag[16]) {
    unsigned int k[8];
    memcpy(k, key, 32);
    unsigned int ctr[4];
    ctr[0] = 0;
    memcpy(&ctr[1], nonce, 12);

    /* generate poly key from block 0 */
    unsigned char polykey[64];
    unsigned char zeros[64] = {0};
    ChaCha20_ctr32(polykey, zeros, 64, k, ctr);

    /* encrypt with counter = 1 */
    ctr[0] = 1;
    pool_crypt(k, ctr, pt, ct, n);

    /* poly1305 over aad || pad || ct || pad || lens */
    void *ctx = malloc(Poly1305_ctx_size());
    Poly1305_Init(ctx, polykey);
    if (aad && aad_len) {
        Poly1305_Update(ctx, aad, aad_len);
        size_t pad = (16 - (aad_len & 15)) & 15;
        if (pad) {
            unsigned char z[16] = {0};
            Poly1305_Update(ctx, z, pad);
        }
    }
    Poly1305_Update(ctx, ct, n);
    size_t pad = (16 - (n & 15)) & 15;
    if (pad) {
        unsigned char z[16] = {0};
        Poly1305_Update(ctx, z, pad);
    }
    unsigned char lens[16];
    uint64_t al = aad_len, cl = n;
    memcpy(lens, &al, 8);
    memcpy(lens+8, &cl, 8);
    Poly1305_Update(ctx, lens, 16);
    Poly1305_Final(ctx, tag);
    free(ctx);
}

int main() {
    size_t n = 40000ull * 1024ull;
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *ct = aligned_alloc(64, n);
    unsigned char *ct_ref = aligned_alloc(64, n+16);
    memset(pt, 0x5a, n);
    unsigned char key[32], nonce[12], aad[32];
    memset(key, 0x11, 32);
    memset(nonce, 0x22, 12);
    memset(aad, 0x33, 32);

    pool_init();

    /* reference via EVP */
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int len=0, tmplen=0;
    EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &len, aad, 32);
    EVP_EncryptUpdate(ctx, ct_ref, &len, pt, (int)n);
    EVP_EncryptFinal_ex(ctx, ct_ref+len, &tmplen);
    unsigned char tag_ref[16];
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag_ref);

    unsigned char tag[16];
    /* warmup */
    aead_encrypt(key, nonce, aad, 32, pt, ct, n, tag);
    printf("match ct %d tag %d\n", memcmp(ct, ct_ref, n)==0, memcmp(tag, tag_ref, 16)==0);
    if (memcmp(tag, tag_ref, 16)) {
        printf("tag ours "); for (int i=0;i<16;i++) printf("%02x", tag[i]);
        printf("\ntag ref  "); for (int i=0;i<16;i++) printf("%02x", tag_ref[i]);
        printf("\n");
    }

    double t0 = now();
    int reps = 5;
    for (int i = 0; i < reps; i++) aead_encrypt(key, nonce, aad, 32, pt, ct, n, tag);
    double t1 = now();
    printf("parallel aead %d threads: %.4f s/op\n", NTH, (t1-t0)/reps);

    /* no aad */
    t0 = now();
    for (int i = 0; i < reps; i++) aead_encrypt(key, nonce, NULL, 0, pt, ct, n, tag);
    t1 = now();
    printf("parallel aead no aad: %.4f s/op\n", (t1-t0)/reps);

    /* reference time */
    t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &len, aad, 32);
        EVP_EncryptUpdate(ctx, ct_ref, &len, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct_ref+len, &tmplen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag_ref);
    }
    t1 = now();
    printf("evp ref: %.4f s/op  speedup %.2f\n", (t1-t0)/reps, ((t1-t0)/reps) / ((t1-t0)/reps));
    return 0;
}
EOF
