#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdint.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

#define NTH 6
static unsigned char *A, *B;
static size_t N;
static void *copy_job(void *arg) {
    int id = (int)(intptr_t)arg;
    size_t chunk = N / NTH;
    size_t off = id * chunk;
    size_t len = (id == NTH-1) ? N - off : chunk;
    memcpy(B + off, A + off, len);
    return NULL;
}
static void *xor_job(void *arg) {
    int id = (int)(intptr_t)arg;
    size_t chunk = N / NTH;
    size_t off = id * chunk;
    size_t len = (id == NTH-1) ? N - off : chunk;
    unsigned char *a = A + off, *b = B + off;
    for (size_t i = 0; i < len; i++) b[i] = a[i] ^ 0x5a;
    return NULL;
}

int main() {
    N = 40000ull * 1024ull;
    A = aligned_alloc(64, N);
    B = aligned_alloc(64, N);
    memset(A, 1, N);
    memset(B, 2, N);
    int reps = 5;
    double t0 = now();
    for (int r = 0; r < reps; r++) memcpy(B, A, N);
    double t1 = now();
    printf("memcpy 1 thread: %.4f s  %.1f GB/s\n", (t1-t0)/reps, (N/(t1-t0)*reps)/1e9);

    pthread_t th[NTH];
    t0 = now();
    for (int r = 0; r < reps; r++) {
        for (int i = 0; i < NTH; i++) pthread_create(&th[i], NULL, copy_job, (void*)(intptr_t)i);
        for (int i = 0; i < NTH; i++) pthread_join(th[i], NULL);
    }
    t1 = now();
    printf("memcpy %d spawn: %.4f s  %.1f GB/s\n", NTH, (t1-t0)/reps, (N/(t1-t0)*reps)/1e9);

    t0 = now();
    for (int r = 0; r < reps; r++) {
        for (int i = 0; i < NTH; i++) pthread_create(&th[i], NULL, xor_job, (void*)(intptr_t)i);
        for (int i = 0; i < NTH; i++) pthread_join(th[i], NULL);
    }
    t1 = now();
    printf("xor %d spawn: %.4f s  %.1f GB/s (counted as N bytes)\n", NTH, (t1-t0)/reps, (N/(t1-t0)*reps)/1e9);
    return 0;
}
