/* 4-way AVX2 ChaCha20 (8 rounds doubled = 20) XOR. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <immintrin.h>
#include <pthread.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);

static inline __m256i rotl_epi32(__m256i x, int n) {
    return _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32 - n));
}

static inline void quarter(__m256i *a, __m256i *b, __m256i *c, __m256i *d) {
    *a = _mm256_add_epi32(*a, *b); *d = _mm256_xor_si256(*d, *a); *d = rotl_epi32(*d, 16);
    *c = _mm256_add_epi32(*c, *d); *b = _mm256_xor_si256(*b, *c); *b = rotl_epi32(*b, 12);
    *a = _mm256_add_epi32(*a, *b); *d = _mm256_xor_si256(*d, *a); *d = rotl_epi32(*d, 8);
    *c = _mm256_add_epi32(*c, *d); *b = _mm256_xor_si256(*b, *c); *b = rotl_epi32(*b, 7);
}

/* Process 256 bytes (4 blocks) starting at block counter `counter0` (the ChaCha counter word). */
static void chacha4(unsigned char *out, const unsigned char *in,
                    const unsigned int key[8], const unsigned int nonce[3], uint32_t counter0) {
    const __m256i c0 = _mm256_set1_epi32(0x61707865);
    const __m256i c1 = _mm256_set1_epi32(0x3320646e);
    const __m256i c2 = _mm256_set1_epi32(0x79622d32);
    const __m256i c3 = _mm256_set1_epi32(0x6b206574);
    const __m256i k0 = _mm256_set1_epi32(key[0]);
    const __m256i k1 = _mm256_set1_epi32(key[1]);
    const __m256i k2 = _mm256_set1_epi32(key[2]);
    const __m256i k3 = _mm256_set1_epi32(key[3]);
    const __m256i k4 = _mm256_set1_epi32(key[4]);
    const __m256i k5 = _mm256_set1_epi32(key[5]);
    const __m256i k6 = _mm256_set1_epi32(key[6]);
    const __m256i k7 = _mm256_set1_epi32(key[7]);
    const __m256i n0 = _mm256_set1_epi32(nonce[0]);
    const __m256i n1 = _mm256_set1_epi32(nonce[1]);
    const __m256i n2 = _mm256_set1_epi32(nonce[2]);
    __m256i ctr = _mm256_set_epi32(counter0+3, counter0+2, counter0+1, counter0+0,
                                   counter0+3, counter0+2, counter0+1, counter0+0);
    /* Wait: set_epi32 is hi to lo across the 8 lanes? 
       _mm256_set_epi32(e7,e6,e5,e4,e3,e2,e1,e0) where e0 is lowest lane.
       We want lanes 0..3 = counter0..+3 and lanes 4..7 = counter0..+3 as well? 
       No: 256-bit has 8 lanes of 32-bit. We want 4 independent blocks, so only 4 counters.
       Using 8 lanes would be 8-way which needs AVX2 8x32 = yes 8 blocks of the counter word only.
       Let's do 4-way properly: broadcast and add lane offsets of 4 (one per block), but 8 lanes means 8 blocks!
       AVX2 can do 8-way ChaCha20 (8 blocks = 512 bytes) with the same quarterround ops.
       Let's do 8-way. */
}

/* 8-way: 512 bytes per call */
static void chacha8(unsigned char *out, const unsigned char *in,
                    const unsigned int key[8], const unsigned int nonce[3], uint32_t counter0) {
    __m256i x0 = _mm256_set1_epi32(0x61707865);
    __m256i x1 = _mm256_set1_epi32(0x3320646e);
    __m256i x2 = _mm256_set1_epi32(0x79622d32);
    __m256i x3 = _mm256_set1_epi32(0x6b206574);
    __m256i x4 = _mm256_set1_epi32(key[0]);
    __m256i x5 = _mm256_set1_epi32(key[1]);
    __m256i x6 = _mm256_set1_epi32(key[2]);
    __m256i x7 = _mm256_set1_epi32(key[3]);
    __m256i x8 = _mm256_set1_epi32(key[4]);
    __m256i x9 = _mm256_set1_epi32(key[5]);
    __m256i x10 = _mm256_set1_epi32(key[6]);
    __m256i x11 = _mm256_set1_epi32(key[7]);
    __m256i x12 = _mm256_add_epi32(_mm256_set1_epi32(counter0),
                                   _mm256_set_epi32(7,6,5,4,3,2,1,0));
    __m256i x13 = _mm256_set1_epi32(nonce[0]);
    __m256i x14 = _mm256_set1_epi32(nonce[1]);
    __m256i x15 = _mm256_set1_epi32(nonce[2]);

    __m256i s0=x0,s1=x1,s2=x2,s3=x3,s4=x4,s5=x5,s6=x6,s7=x7;
    __m256i s8=x8,s9=x9,s10=x10,s11=x11,s12=x12,s13=x13,s14=x14,s15=x15;

    for (int i = 0; i < 10; i++) {
        /* column rounds */
        quarter(&x0, &x4, &x8, &x12);
        quarter(&x1, &x5, &x9, &x13);
        quarter(&x2, &x6, &x10, &x14);
        quarter(&x3, &x7, &x11, &x15);
        /* diagonal rounds */
        quarter(&x0, &x5, &x10, &x15);
        quarter(&x1, &x6, &x11, &x12);
        quarter(&x2, &x7, &x8, &x13);
        quarter(&x3, &x4, &x9, &x14);
    }
    x0 = _mm256_add_epi32(x0, s0);
    x1 = _mm256_add_epi32(x1, s1);
    x2 = _mm256_add_epi32(x2, s2);
    x3 = _mm256_add_epi32(x3, s3);
    x4 = _mm256_add_epi32(x4, s4);
    x5 = _mm256_add_epi32(x5, s5);
    x6 = _mm256_add_epi32(x6, s6);
    x7 = _mm256_add_epi32(x7, s7);
    x8 = _mm256_add_epi32(x8, s8);
    x9 = _mm256_add_epi32(x9, s9);
    x10 = _mm256_add_epi32(x10, s10);
    x11 = _mm256_add_epi32(x11, s11);
    x12 = _mm256_add_epi32(x12, s12);
    x13 = _mm256_add_epi32(x13, s13);
    x14 = _mm256_add_epi32(x14, s14);
    x15 = _mm256_add_epi32(x15, s15);

    /* Transpose 8 blocks of 16 words (column-major lanes) into 8 sequential 64-byte blocks.
       Each xi holds word i of 8 blocks. We want block b's words contiguous.
       Store lanes then interleave. Simpler: extract lane by lane. */
    uint32_t w0[8], w1[8], w2[8], w3[8], w4[8], w5[8], w6[8], w7[8];
    uint32_t w8[8], w9[8], w10[8], w11[8], w12[8], w13[8], w14[8], w15[8];
    _mm256_storeu_si256((__m256i*)w0, x0);
    _mm256_storeu_si256((__m256i*)w1, x1);
    _mm256_storeu_si256((__m256i*)w2, x2);
    _mm256_storeu_si256((__m256i*)w3, x3);
    _mm256_storeu_si256((__m256i*)w4, x4);
    _mm256_storeu_si256((__m256i*)w5, x5);
    _mm256_storeu_si256((__m256i*)w6, x6);
    _mm256_storeu_si256((__m256i*)w7, x7);
    _mm256_storeu_si256((__m256i*)w8, x8);
    _mm256_storeu_si256((__m256i*)w9, x9);
    _mm256_storeu_si256((__m256i*)w10, x10);
    _mm256_storeu_si256((__m256i*)w11, x11);
    _mm256_storeu_si256((__m256i*)w12, x12);
    _mm256_storeu_si256((__m256i*)w13, x13);
    _mm256_storeu_si256((__m256i*)w14, x14);
    _mm256_storeu_si256((__m256i*)w15, x15);

    uint32_t blocks[8][16];
    for (int b = 0; b < 8; b++) {
        blocks[b][0]=w0[b]; blocks[b][1]=w1[b]; blocks[b][2]=w2[b]; blocks[b][3]=w3[b];
        blocks[b][4]=w4[b]; blocks[b][5]=w5[b]; blocks[b][6]=w6[b]; blocks[b][7]=w7[b];
        blocks[b][8]=w8[b]; blocks[b][9]=w9[b]; blocks[b][10]=w10[b]; blocks[b][11]=w11[b];
        blocks[b][12]=w12[b]; blocks[b][13]=w13[b]; blocks[b][14]=w14[b]; blocks[b][15]=w15[b];
    }
    /* XOR with input */
    const uint32_t *inp = (const uint32_t*)in;
    uint32_t *outp = (uint32_t*)out;
    for (int b = 0; b < 8; b++) {
        for (int i = 0; i < 16; i++) {
            outp[b*16+i] = blocks[b][i] ^ inp[b*16+i];
        }
    }
}

static void crypt_avx2(unsigned char *out, const unsigned char *in, size_t len,
                       const unsigned int key[8], const unsigned int counter[4]) {
    unsigned int nonce[3] = {counter[1], counter[2], counter[3]};
    uint32_t ctr = counter[0];
    size_t off = 0;
    while (off + 512 <= len) {
        chacha8(out+off, in+off, key, nonce, ctr);
        ctr += 8;
        off += 512;
    }
    if (off < len) {
        unsigned int c[4] = {ctr, nonce[0], nonce[1], nonce[2]};
