static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

#define N (64ull<<20) /* 64 MB */
#define NTH 6

static unsigned char *a, *b, *c;

static void *triad(void *arg) {
    int id = (int)(intptr_t)arg;
    size_t chunk = N / NTH;
    size_t off = id * chunk;
    size_t len = (id==NTH-1)? N-off : chunk;
    unsigned char *aa=a+off, *bb=b+off, *cc=c+off;
    for (size_t i=0;i<len;i++) aa[i] = bb[i] + cc[i];
    return NULL;
}
static void *copyj(void *arg) {
    int id = (int)(intptr_t)arg;
    size_t chunk = N / NTH;
    size_t off = id * chunk;
    size_t len = (id==NTH-1)? N-off : chunk;
    memcpy(a+off, b+off, len);
    return NULL;
}

int main() {
    a = aligned_alloc(64, N);
    b = aligned_alloc(64, N);
    c = aligned_alloc(64, N);
    memset(a, 1, N); memset(b, 2, N); memset(c, 3, N);
    int reps = 5;
    /* single memcpy */
    double t0 = now();
    for (int i=0;i<reps;i++) memcpy(a, b, N);
    double t1 = now();
    printf("memcpy1 64MB: %.4f s  copy %.1f GB/s  traffic %.1f GB/s\n",
           (t1-t0)/reps, (N/((t1-t0)/reps))/1e9, (2.0*N/((t1-t0)/reps))/1e9);

    pthread_t th[12];
    t0 = now();
    for (int r=0;r<reps;r++) {
        for (int i=0;i<NTH;i++) pthread_create(&th[i], NULL, copyj, (void*)(intptr_t)i);
        for (int i=0;i<NTH;i++) pthread_join(th[i], NULL);
    }
    t1 = now();
    printf("memcpy%d spawn 64MB: %.4f s  copy %.1f GB/s\n", NTH, (t1-t0)/reps, (N/((t1-t0)/reps))/1e9);

    /* persistent? just measure raw with OpenMP-like via already warm. Use 12 threads no, spawn overhead on 64MB is small. */
    int nth=12;
    /* redefine by calling copy with 12 - I'll just loop in main with manual split using already created? skip */
    t0 = now();
    for (int r=0;r<reps;r++) {
        for (int i=0;i<nth;i++) pthread_create(&th[i], NULL, copyj, (void*)(intptr_t)i);
        for (int i=0;i<nth;i++) pthread_join(th[i], NULL);
    }
    t1 = now();
    printf("note NTH macro is 6, this still uses 6 workers if copyj uses NTH. ignore if same.\n");
    return 0;
}
