#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>
#include <openssl/evp.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);
size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

#define MAXTH 12
static int NTH = 6;

typedef struct {
    const unsigned char *in;
    unsigned char *out;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
} job_t;

static void *run_job(void *arg) {
    job_t *j = arg;
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, j->counter);
    return NULL;
}

/* Encrypt pt->ct with ChaCha20 starting at counter word = start_counter, nonce in counter[1..3]. */
static void parallel_chacha(const unsigned int key[8], uint32_t start_counter,
                            const unsigned int nonce[3],
                            const unsigned char *in, unsigned char *out, size_t n) {
    if (n == 0) return;
    int nth = NTH;
    if (n < (size_t)nth * 4096) nth = 1;
    if (nth == 1) {
        unsigned int c[4] = {start_counter, nonce[0], nonce[1], nonce[2]};
        ChaCha20_ctr32(out, in, n, key, c);
        return;
    }
    pthread_t th[MAXTH];
    job_t jobs[MAXTH];
    size_t chunk = (n / nth) & ~63ull;
    if (chunk == 0) {
        unsigned int c[4] = {start_counter, nonce[0], nonce[1], nonce[2]};
        ChaCha20_ctr32(out, in, n, key, c);
        return;
    }
    size_t off = 0;
    int launched = 0;
    for (int i = 0; i < nth; i++) {
        size_t len = (i == nth - 1) ? (n - off) : chunk;
        memcpy(jobs[i].key, key, 32);
        jobs[i].counter[0] = start_counter + (uint32_t)(off / 64);
        jobs[i].counter[1] = nonce[0];
        jobs[i].counter[2] = nonce[1];
        jobs[i].counter[3] = nonce[2];
        jobs[i].in = in + off;
        jobs[i].out = out + off;
        jobs[i].len = len;
        pthread_create(&th[i], NULL, run_job, &jobs[i]);
        launched++;
        off += len;
    }
    for (int i = 0; i < launched; i++) pthread_join(th[i], NULL);
}

static void aead(const unsigned char keyb[32], const unsigned char nonce[12],
                 const unsigned char *aad, size_t aad_len,
                 const unsigned char *pt, unsigned char *ct, size_t n,
                 unsigned char tag[16]) {
    unsigned int key[8];
    memcpy(key, keyb, 32);
    unsigned int nv[3];
    memcpy(nv, nonce, 12);

    unsigned char polykey[64];
    unsigned char zeros[64] = {0};
    unsigned int c0[4] = {0, nv[0], nv[1], nv[2]};
    ChaCha20_ctr32(polykey, zeros, 64, key, c0);

    parallel_chacha(key, 1, nv, pt, ct, n);

    /* poly1305 */
    size_t ctxsz = Poly1305_ctx_size();
    void *ctx = malloc(ctxsz);
    Poly1305_Init(ctx, polykey);
    if (aad_len) {
        Poly1305_Update(ctx, aad, aad_len);
        size_t pad = (16 - (aad_len & 15)) & 15;
        if (pad) {
            unsigned char z[16] = {0};
            Poly1305_Update(ctx, z, pad);
        }
    }
    if (n) {
        Poly1305_Update(ctx, ct, n);
        size_t pad = (16 - (n & 15)) & 15;
        if (pad) {
            unsigned char z[16] = {0};
            Poly1305_Update(ctx, z, pad);
        }
    }
    unsigned char lens[16];
    uint64_t al = aad_len, cl = n;
    memcpy(lens, &al, 8);
    memcpy(lens + 8, &cl, 8);
    Poly1305_Update(ctx, lens, 16);
    Poly1305_Final(ctx, tag);
    free(ctx);
}

/* Exported for ctypes: 
   void encrypt(key, nonce, aad, aad_len, pt, pt_len, ct_out, tag_out, nthreads)
*/
void chacha_aead_encrypt(const unsigned char *key, const unsigned char *nonce,
                         const unsigned char *aad, size_t aad_len,
                         const unsigned char *pt, size_t pt_len,
                         unsigned char *ct, unsigned char *tag, int nthreads) {
    NTH = nthreads > 0 && nthreads <= MAXTH ? nthreads : 6;
    aead(key, nonce, aad, aad_len, pt, ct, pt_len, tag);
}

#ifdef BENCH
#include <time.h>
static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}
int main() {
    size_t n = 40000ull * 1024ull;
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *ct = aligned_alloc(64, n);
    unsigned char *ct_ref = aligned_alloc(64, n + 16);
    memset(pt, 0x5a, n);
    unsigned char key[32], nonce[12], aad[32], tag[16], tag_ref[16];
    for (int i = 0; i < 32; i++) key[i] = (unsigned char)(i * 7 + 3);
    for (int i = 0; i < 12; i++) nonce[i] = (unsigned char)(i * 9 + 1);
    for (int i = 0; i < 32; i++) aad[i] = (unsigned char)(i + 5);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int len = 0, tmplen = 0;
    EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &len, aad, 32);
    EVP_EncryptUpdate(ctx, ct_ref, &len, pt, (int)n);
    EVP_EncryptFinal_ex(ctx, ct_ref + len, &tmplen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag_ref);

    for (int th = 1; th <= 12; th++) {
        NTH = th;
        aead(key, nonce, aad, 32, pt, ct, n, tag);
        int ok = memcmp(ct, ct_ref, n) == 0 && memcmp(tag, tag_ref, 16) == 0;
        double t0 = now();
        int reps = 3;
        for (int i = 0; i < reps; i++) aead(key, nonce, aad, 32, pt, ct, n, tag);
        double t1 = now();
        printf("th=%2d %.4f s ok=%d\n", th, (t1 - t0) / reps, ok);
        if (!ok) {
            printf("  ct match %d tag match %d\n", memcmp(ct, ct_ref, n)==0, memcmp(tag, tag_ref, 16)==0);
            return 1;
        }
    }
    /* empty aad */
    NTH = 6;
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, ct_ref, &len, pt, (int)n);
    EVP_EncryptFinal_ex(ctx, ct_ref + len, &tmplen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag_ref);
    aead(key, nonce, NULL, 0, pt, ct, n, tag);
    printf("no aad match %d\n", memcmp(ct, ct_ref, n)==0 && memcmp(tag, tag_ref, 16)==0);

    /* small message */
    unsigned char spt[100], sct[100], sref[116];
    memset(spt, 0x42, 100);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &len, aad, 32);
    EVP_EncryptUpdate(ctx, sref, &len, spt, 100);
    EVP_EncryptFinal_ex(ctx, sref + len, &tmplen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag_ref);
    aead(key, nonce, aad, 32, spt, sct, 100, tag);
    printf("small match %d\n", memcmp(sct, sref, 100)==0 && memcmp(tag, tag_ref, 16)==0);

    /* empty plaintext */
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &len, aad, 7);
    EVP_EncryptFinal_ex(ctx, sref, &tmplen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag_ref);
    aead(key, nonce, aad, 7, spt, sct, 0, tag);
    printf("empty pt match %d\n", memcmp(tag, tag_ref, 16)==0);
    return 0;
}
#endif
EOF
cc -O3 -DBENCH -I/usr/local/opt/openssl@3/include -L/usr/local/opt/openssl@3/lib -o build/aead_fast build/aead_fast.c -lcrypto -lpthread && ./build/aead_fast"}

