static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    void *h = dlopen("/usr/local/lib/libcrypto.dylib", RTLD_NOW);
    /* hidden symbol: dlsym won't find it. Use the known offset from the image base. */
    /* Find image base via a known exported symbol. */
    void *sym = dlsym(h, "ChaCha20_ctr32");
    printf("ChaCha20_ctr32 runtime %p  fileoff 0x6af40\n", sym);
    uintptr_t base = (uintptr_t)sym - 0x6af40;
    unsigned int *cap = (unsigned int *)(base + 0x4194b0);
    printf("cap @ %p\n", cap);
    for (int i = 0; i < 8; i++) printf("  [%d]=0x%08x\n", i, cap[i]);

    /* bit tests:
       word1 (cap[1]) bit 9 (0x200) -> ssse3 path. 
       word1 bit 11 (0x800) -> 4xop (XOP). We do NOT want this if not AMD XOP.
       Then in 4x: r10 = word1, shr 32 -> that's word2? 
       movq r10 from cap+4 which is cap[1] as 64-bit load! 
       movq  (cap+4), %r10  loads 8 bytes: cap[1] and cap[2].
       testl $0x200, %r10d  -> cap[1] bit 9
       testl $0x800, %r10d  -> cap[1] bit 11  (XOP) -> 4xop
       then in 4x: shrq $32, %r10 -> cap[2], testq $0x20 -> cap[2] bit 5 -> 8x AVX2
    */
    printf("cap[1] bit9 SSSE3 %d bit11 XOP %d\n", (cap[1]>>9)&1, (cap[1]>>11)&1);
    printf("cap[2]=0x%08x bit5 %d\n", cap[2], (cap[2]>>5)&1);

    size_t n = 40000ull*1024ull;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    memset(pt, 1, n);
    unsigned int key[8] = {1,2,3,4,5,6,7,8};
    unsigned int counter[4] = {1,9,10,11};

    double t0 = now();
    for (int i = 0; i < 3; i++) ChaCha20_ctr32(ct, pt, n, key, counter);
    double t1 = now();
    printf("default path: %.4f s\n", (t1-t0)/3);

    /* Force AVX2 8x: set cap[2] bit 5, clear XOP bit */
    unsigned int saved1 = cap[1], saved2 = cap[2];
    cap[1] = saved1 & ~(1u<<11); /* clear XOP */
    cap[1] |= (1u<<9); /* ensure SSSE3 */
    cap[2] = saved2 | (1u<<5); /* AVX2? bit 5 */
    printf("forced cap[1]=0x%08x cap[2]=0x%08x\n", cap[1], cap[2]);
    t0 = now();
    for (int i = 0; i < 3; i++) ChaCha20_ctr32(ct, pt, n, key, counter);
    t1 = now();
    printf("forced bit5: %.4f s\n", (t1-t0)/3);

    /* try other bits in cap[2] */
    for (int b = 0; b < 32; b++) {
        cap[1] = saved1 & ~(1u<<11);
        cap[1] |= (1u<<9);
        cap[2] = saved2 | (1u<<b);
        t0 = now();
        ChaCha20_ctr32(ct, pt, n, key, counter);
        t1 = now();
        printf("bit %2d cap2=0x%08x time %.4f\n", b, cap[2], t1-t0);
    }
    cap[1]=saved1; cap[2]=saved2;
    return 0;
}
