#include <immintrin.h>
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);

static inline __m256i rot16(__m256i x) {
    /* 16-bit rotate within 32-bit lanes: pshufb */
    const __m256i m = _mm256_set_epi8(
        13,12,15,14, 9,8,11,10, 5,4,7,6, 1,0,3,2,
        13,12,15,14, 9,8,11,10, 5,4,7,6, 1,0,3,2);
    return _mm256_shuffle_epi8(x, m);
}
static inline __m256i rot8(__m256i x) {
    const __m256i m = _mm256_set_epi8(
        14,13,12,15, 10,9,8,11, 6,5,4,7, 2,1,0,3,
        14,13,12,15, 10,9,8,11, 6,5,4,7, 2,1,0,3);
    return _mm256_shuffle_epi8(x, m);
}
static inline __m256i rotl(__m256i x, int n) {
    return _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32-n));
}

#define QR(a,b,c,d) do { \
    a = _mm256_add_epi32(a, b); d = rot16(_mm256_xor_si256(d, a)); \
    c = _mm256_add_epi32(c, d); b = rotl(_mm256_xor_si256(b, c), 12); \
    a = _mm256_add_epi32(a, b); d = rot8(_mm256_xor_si256(d, a)); \
    c = _mm256_add_epi32(c, d); b = rotl(_mm256_xor_si256(b, c), 7); \
} while (0)

/* Transpose 8 blocks from word-lanes into sequential 64-byte blocks and XOR input.
   After rounds, x[i] holds word i of 8 blocks (lanes 0..7).
   We want out block b = words 0..15 of lane b, XORed with input.
   Use extract + store. For speed, store to a small stack buffer via lane extraction
   is the bottleneck. Better: use _mm256_permutevar8x32 / unpack to gather words.

   Layout: 8 lanes. We'll write each block by extracting 128-bit halves.
   A known fast approach: store all 16 ymm to memory (word-major), then a second
   SIMD transpose. 16*32 = 512 bytes store + transpose + xor + store.

   Let's do an in-register transpose of 8x8 32-bit then handle two halves? 
   Actually 16 words x 8 lanes. Split into two 8x8 matrices (words 0-7 and 8-15).
*/

static inline void transpose8(__m256i *r0, __m256i *r1, __m256i *r2, __m256i *r3,
                              __m256i *r4, __m256i *r5, __m256i *r6, __m256i *r7) {
    /* 8x8 transpose of 32-bit elements. Input: ri has element i of each of 8 rows? 
       We want output ri = row i (8 consecutive words of block i)? 
       Standard 8x8 epi32 transpose. */
    __m256i t0, t1, t2, t3, t4, t5, t6, t7;
    t0 = _mm256_unpacklo_epi32(*r0, *r1);
    t1 = _mm256_unpackhi_epi32(*r0, *r1);
    t2 = _mm256_unpacklo_epi32(*r2, *r3);
    t3 = _mm256_unpackhi_epi32(*r2, *r3);
    t4 = _mm256_unpacklo_epi32(*r4, *r5);
    t5 = _mm256_unpackhi_epi32(*r4, *r5);
    t6 = _mm256_unpacklo_epi32(*r6, *r7);
    t7 = _mm256_unpackhi_epi32(*r6, *r7);

    __m256i u0, u1, u2, u3, u4, u5, u6, u7;
    u0 = _mm256_unpacklo_epi64(t0, t2);
    u1 = _mm256_unpackhi_epi64(t0, t2);
    u2 = _mm256_unpacklo_epi64(t1, t3);
    u3 = _mm256_unpackhi_epi64(t1, t3);
    u4 = _mm256_unpacklo_epi64(t4, t6);
    u5 = _mm256_unpackhi_epi64(t4, t6);
    u6 = _mm256_unpacklo_epi64(t5, t7);
    u7 = _mm256_unpackhi_epi64(t5, t7);

    /* Now need to swap 128-bit lanes between low group and high group. */
    *r0 = _mm256_permute2x128_si256(u0, u4, 0x20);
    *r1 = _mm256_permute2x128_si256(u1, u5, 0x20);
    *r2 = _mm256_permute2x128_si256(u2, u6, 0x20);
    *r3 = _mm256_permute2x128_si256(u3, u7, 0x20);
    *r4 = _mm256_permute2x128_si256(u0, u4, 0x31);
    *r5 = _mm256_permute2x128_si256(u1, u5, 0x31);
    *r6 = _mm256_permute2x128_si256(u2, u6, 0x31);
    *r7 = _mm256_permute2x128_si256(u3, u7, 0x31);
}

static void chacha8_xor(unsigned char *out, const unsigned char *in,
                        const unsigned int key[8], const unsigned int nonce[3], uint32_t counter) {
    __m256i x0 = _mm256_set1_epi32(0x61707865);
    __m256i x1 = _mm256_set1_epi32(0x3320646e);
    __m256i x2 = _mm256_set1_epi32(0x79622d32);
    __m256i x3 = _mm256_set1_epi32(0x6b206574);
    __m256i x4 = _mm256_set1_epi32(key[0]);
    __m256i x5 = _mm256_set1_epi32(key[1]);
    __m256i x6 = _mm256_set1_epi32(key[2]);
    __m256i x7 = _mm256_set1_epi32(key[3]);
    __m256i x8 = _mm256_set1_epi32(key[4]);
    __m256i x9 = _mm256_set1_epi32(key[5]);
    __m256i x10 = _mm256_set1_epi32(key[6]);
    __m256i x11 = _mm256_set1_epi32(key[7]);
    __m256i x12 = _mm256_add_epi32(_mm256_set1_epi32((int)counter), _mm256_set_epi32(7,6,5,4,3,2,1,0));
    __m256i x13 = _mm256_set1_epi32(nonce[0]);
    __m256i x14 = _mm256_set1_epi32(nonce[1]);
    __m256i x15 = _mm256_set1_epi32(nonce[2]);

    __m256i s0=x0,s1=x1,s2=x2,s3=x3,s4=x4,s5=x5,s6=x6,s7=x7;
    __m256i s8=x8,s9=x9,s10=x10,s11=x11,s12=x12,s13=x13,s14=x14,s15=x15;

    #pragma unroll 1
    for (int i = 0; i < 10; i++) {
        QR(x0, x4, x8, x12);
        QR(x1, x5, x9, x13);
        QR(x2, x6, x10, x14);
        QR(x3, x7, x11, x15);
        QR(x0, x5, x10, x15);
        QR(x1, x6, x11, x12);
        QR(x2, x7, x8, x13);
        QR(x3, x4, x9, x14);
