typedef struct { const unsigned char *in; unsigned char *out; size_t n; unsigned int key[8]; unsigned int counter[4]; } job_t;
static void *run(void *arg) { job_t *j = arg; crypt(j->out, j->in, j->n, j->key, j->counter); return NULL; }

