{"command":"cat > build/fastmod.c << 'EOF'
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);
size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

#define MAXTH 8
static int g_nth = 6;

typedef struct {
    pthread_t th;
    pthread_mutex_t mu;
    pthread_cond_t cv;
    pthread_cond_t done_cv;
    int cmd; /* 0 idle, 1 work, 2 exit */
    int finished;
    const unsigned char *in;
    unsigned char *out;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
} worker_t;

static worker_t workers[MAXTH];
static int pool_ready = 0;

static void *worker_fn(void *arg) {
    worker_t *w = arg;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (w->cmd == 0) pthread_cond_wait(&w->cv, &w->mu);
        if (w->cmd == 2) {
            pthread_mutex_unlock(&w->mu);
            return NULL;
        }
        const unsigned char *in = w->in;
        unsigned char *out = w->out;
        size_t len = w->len;
        unsigned int key[8], counter[4];
        memcpy(key, w->key, 32);
        memcpy(counter, w->counter, 16);
        pthread_mutex_unlock(&w->mu);

        ChaCha20_ctr32(out, in, len, key, counter);

        pthread_mutex_lock(&w->mu);
        w->cmd = 0;
        w->finished = 1;
        pthread_cond_signal(&w->done_cv);
    }
}

static void pool_init(int nth) {
    if (pool_ready) return;
    if (nth < 1) nth = 1;
    if (nth > MAXTH) nth = MAXTH;
    g_nth = nth;
    for (int i = 0; i < g_nth; i++) {
        pthread_mutex_init(&workers[i].mu, NULL);
        pthread_cond_init(&workers[i].cv, NULL);
        pthread_cond_init(&workers[i].done_cv, NULL);
        workers[i].cmd = 0;
        workers[i].finished = 1;
        pthread_create(&workers[i].th, NULL, worker_fn, &workers[i]);
    }
    pool_ready = 1;
}

static void parallel_chacha(const unsigned int key[8], uint32_t start_counter,
                            const unsigned int nonce[3],
                            const unsigned char *in, unsigned char *out, size_t n) {
    if (n == 0) return;
    int nth = g_nth;
    if (n < (size_t)nth * 8192) nth = 1;
    if (nth == 1) {
        unsigned int c[4] = {start_counter, nonce[0], nonce[1], nonce[2]};
        ChaCha20_ctr32(out, in, n, key, c);
        return;
    }
    size_t chunk = (n / nth) & ~63ull;
    if (chunk == 0) {
        unsigned int c[4] = {start_counter, nonce[0], nonce[1], nonce[2]};
        ChaCha20_ctr32(out, in, n, key, c);
        return;
    }
    size_t off = 0;
    int launched = 0;
    for (int i = 0; i < nth; i++) {
        size_t len = (i == nth - 1) ? (n - off) : chunk;
        worker_t *w = &workers[i];
        pthread_mutex_lock(&w->mu);
        memcpy(w->key, key, 32);
        w->counter[0] = start_counter + (uint32_t)(off / 64);
        w->counter[1] = nonce[0];
        w->counter[2] = nonce[1];
        w->counter[3] = nonce[2];
        w->in = in + off;
        w->out = out + off;
        w->len = len;
        w->finished = 0;
        w->cmd = 1;
        pthread_cond_signal(&w->cv);
        pthread_mutex_unlock(&w->mu);
        off += len;
        launched++;
    }
    for (int i = 0; i < launched; i++) {
        worker_t *w = &workers[i];
        pthread_mutex_lock(&w->mu);
        while (!w->finished) pthread_cond_wait(&w->done_cv, &w->mu);
        pthread_mutex_unlock(&w->mu);
    }
}

static PyObject *py_encrypt(PyObject *self, PyObject *args) {
    const unsigned char *key, *nonce, *aad, *pt;
    Py_ssize_t key_len, nonce_len, aad_len, pt_len;
    int nth = 6;
    if (!PyArg_ParseTuple(args, "y#y#y#y#|i",
                          &key, &key_len, &nonce, &nonce_len,
                          &aad, &aad_len, &pt, &pt_len, &nth)) {
        return NULL;
    }
    if (key_len != 32 || nonce_len != 12) {
        PyErr_SetString(PyExc_ValueError, "bad key/nonce size");
        return NULL;
    }
    pool_init(nth);

    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, pt_len);
    PyObject *tag_obj = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct_obj || !tag_obj) {
        Py_XDECREF(ct_obj);
        Py_XDECREF(tag_obj);
        return NULL;
    }
    unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_obj);
    unsigned char *tag = (unsigned char *)PyBytes_AS_STRING(tag_obj);

    unsigned int keyu[8];
    memcpy(keyu, key, 32);
    unsigned int nv[3];
    memcpy(nv, nonce, 12);

    unsigned char polykey[64];
    unsigned char zeros[64] = {0};
    unsigned int c0[4] = {0, nv[0], nv[1], nv[2]};
    ChaCha20_ctr32(polykey, zeros, 64, keyu, c0);

    parallel_chacha(keyu, 1, nv, pt, ct, (size_t)pt_len);

    /* poly1305. Use a static buffer to avoid malloc. ctx size is 248. */
    static unsigned char ctxbuf[512];
    void *ctx = ctxbuf;
    Poly1305_Init(ctx, polykey);
    if (aad_len) {
        Poly1305_Update(ctx, aad, (size_t)aad_len);
        size_t pad = (16 - (aad_len & 15)) & 15;
        if (pad) {
            unsigned char z[16] = {0};
            Poly1305_Update(ctx, z, pad);
        }
    }
    if (pt_len) {
        Poly1305_Update(ctx, ct, (size_t)pt_len);
        size_t pad = (16 - (pt_len & 15)) & 15;
        if (pad) {
            unsigned char z[16] = {0};
            Poly1305_Update(ctx, z, pad);
        }
    }
    unsigned char lens[16];
    uint64_t al = (uint64_t)aad_len, cl = (uint64_t)pt_len;
    memcpy(lens, &al, 8);
    memcpy(lens + 8, &cl, 8);
    Poly1305_Update(ctx, lens, 16);
    Poly1305_Final(ctx, tag);

    PyObject *result = PyTuple_Pack(2, ct_obj, tag_obj);
    Py_DECREF(ct_obj);
    Py_DECREF(tag_obj);
    return result;
}

static PyMethodDef methods[] = {
    {"encrypt", py_encrypt, METH_VARARGS, "ChaCha20-Poly1305 encrypt"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "fastmod", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_fastmod(void) { return PyModule_Create(&moduledef); }
EOF
