{"command":"# true bandwidth with persistent threads, large buffer
cat > build/bw2.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define NTH 6
#define N (256ull<<20)

static unsigned char *a, *b;
static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

typedef struct {
    pthread_t th; pthread_mutex_t mu; pthread_cond_t cv, done;
    int cmd, finished, id;
} w_t;
static w_t ws[NTH];

static void *fn(void *arg) {
    w_t *w = arg;
    size_t chunk = N / NTH;
    size_t off = w->id * chunk;
    size_t len = (w->id==NTH-1)? N-off : chunk;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (w->cmd==0) pthread_cond_wait(&w->cv, &w->mu);
        if (w->cmd==2) { pthread_mutex_unlock(&w->mu); return NULL; }
        pthread_mutex_unlock(&w->mu);
        /* STREAM copy */
        memcpy(a+off, b+off, len);
        pthread_mutex_lock(&w->mu);
        w->cmd=0; w->finished=1; pthread_cond_signal(&w->done);
    }
}

int main() {
    a = aligned_alloc(64, N); b = aligned_alloc(64, N);
    memset(a, 1, N); memset(b, 2, N);
    for (int i=0;i<NTH;i++) {
        pthread_mutex_init(&ws[i].mu, NULL);
        pthread_cond_init(&ws[i].cv, NULL);
        pthread_cond_init(&ws[i].done, NULL);
        ws[i].cmd=0; ws[i].id=i; ws[i].finished=1;
        pthread_create(&ws[i].th, NULL, fn, &ws[i]);
    }
    int reps=5;
    double t0=now();
    for (int r=0;r<reps;r++) {
        for (int i=0;i<NTH;i++) {
            pthread_mutex_lock(&ws[i].mu);
            ws[i].finished=0; ws[i].cmd=1; pthread_cond_signal(&ws[i].cv);
            pthread_mutex_unlock(&ws[i].mu);
        }
        for (int i=0;i<NTH;i++) {
            pthread_mutex_lock(&ws[i].mu);
            while (!ws[i].finished) pthread_cond_wait(&ws[i].done, &ws[i].mu);
            pthread_mutex_unlock(&ws[i].mu);
        }
    }
    double t1=now();
    double sec=(t1-t0)/reps;
    printf("persistent memcpy 256MB x%d: %.4f s  copy %.1f GB/s  traffic %.1f GB/s\n", NTH, sec, (N/sec)/1e9, (2.0*N/sec)/1e9);

    /* single thread */
    t0=now();
    for (int r=0;r<reps;r++) memcpy(a,b,N);
    t1=now();
    sec=(t1-t0)/reps;
    printf("single memcpy 256MB: %.4f s  copy %.1f GB/s traffic %.1f\n", sec, (N/sec)/1e9, (2.0*N/sec)/1e9);
    return 0;
}
EOF
