static PyObject *py_encrypt_bytes_inplace(PyObject *self, PyObject *args) {
    const unsigned char *key, *nonce, *aad;
    Py_ssize_t key_len, nonce_len, aad_len;
    PyObject *pt_obj;
    int nth = 6;
    if (!PyArg_ParseTuple(args, "y#y#y#O|i",
                          &key, &key_len, &nonce, &nonce_len,
                          &aad, &aad_len, &pt_obj, &nth)) {
        return NULL;
    }
    if (key_len != 32 || nonce_len != 12) {
        PyErr_SetString(PyExc_ValueError, "bad key/nonce size");
        return NULL;
    }
    if (!PyBytes_Check(pt_obj)) {
        PyErr_SetString(PyExc_TypeError, "plaintext must be bytes");
        return NULL;
    }
    pool_init(nth);
    unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(pt_obj);
    Py_ssize_t pt_len = PyBytes_GET_SIZE(pt_obj);

    PyObject *tag_obj = PyBytes_FromStringAndSize(NULL, 16);
    if (!tag_obj) return NULL;
    unsigned char *tag = (unsigned char *)PyBytes_AS_STRING(tag_obj);

    unsigned int keyu[8];
    memcpy(keyu, key, 32);
    unsigned int nv[3];
    memcpy(nv, nonce, 12);

    unsigned char polykey[64];
    unsigned char zeros[64] = {0};
    unsigned int c0[4] = {0, nv[0], nv[1], nv[2]};
    ChaCha20_ctr32(polykey, zeros, 64, keyu, c0);
    parallel_chacha(keyu, 1, nv, ct, ct, (size_t)pt_len);

    static unsigned char ctxbuf[512];
    void *ctx = ctxbuf;
    Poly1305_Init(ctx, polykey);
    if (aad_len) {
        Poly1305_Update(ctx, aad, (size_t)aad_len);
        size_t pad = (16 - (aad_len & 15)) & 15;
        if (pad) {
            unsigned char z[16] = {0};
            Poly1305_Update(ctx, z, pad);
        }
    }
    if (pt_len) {
        Poly1305_Update(ctx, ct, (size_t)pt_len);
        size_t pad = (16 - (pt_len & 15)) & 15;
        if (pad) {
            unsigned char z[16] = {0};
            Poly1305_Update(ctx, z, pad);
        }
    }
    unsigned char lens[16];
    uint64_t al = (uint64_t)aad_len, cl = (uint64_t)pt_len;
    memcpy(lens, &al, 8);
    memcpy(lens + 8, &cl, 8);
    Poly1305_Update(ctx, lens, 16);
    Poly1305_Final(ctx, tag);

    Py_INCREF(pt_obj);
    PyObject *result = PyTuple_Pack(2, pt_obj, tag_obj);
    Py_DECREF(pt_obj);
    Py_DECREF(tag_obj);
    return result;
