void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);

/* 4-block SSSE3/AVX-style but in AVX2 128-bit lanes duplicated? 
   Do 4 independent blocks in xmm, which is what openssl 4x does. 
   Measure a carefully unrolled 4-block using SSE. */

static inline __m128i rot16(__m128i x) {
    return _mm_shuffle_epi8(x, _mm_set_epi8(13,12,15,14, 9,8,11,10, 5,4,7,6, 1,0,3,2));
}
static inline __m128i rot8(__m128i x) {
    return _mm_shuffle_epi8(x, _mm_set_epi8(14,13,12,15, 10,9,8,11, 6,5,4,7, 2,1,0,3));
}
static inline __m128i rotl(__m128i x, int n) {
    return _mm_or_si128(_mm_slli_epi32(x, n), _mm_srli_epi32(x, 32-n));
}
#define QR(a,b,c,d) do { \
    a = _mm_add_epi32(a, b); d = rot16(_mm_xor_si128(d, a)); \
    c = _mm_add_epi32(c, d); b = rotl(_mm_xor_si128(b, c), 12); \
    a = _mm_add_epi32(a, b); d = rot8(_mm_xor_si128(d, a)); \
    c = _mm_add_epi32(c, d); b = rotl(_mm_xor_si128(b, c), 7); \
} while (0)

/* vertical 4 blocks: each xmm holds one word across 4 blocks */
static void chacha4(unsigned char *out, const unsigned char *in,
