    __m128i x7 = _mm_set1_epi32(st[7]);
    __m128i x8 = _mm_set1_epi32(st[8]);
    __m128i x9 = _mm_set1_epi32(st[9]);
    __m128i x10 = _mm_set1_epi32(st[10]);
    __m128i x11 = _mm_set1_epi32(st[11]);
    __m128i x12 = _mm_add_epi32(_mm_set1_epi32(st[12]), _mm_set_epi32(3,2,1,0));
    __m128i x13 = _mm_set1_epi32(st[13]);
    __m128i x14 = _mm_set1_epi32(st[14]);
    __m128i x15 = _mm_set1_epi32(st[15]);
    __m128i s0=x0,s1=x1,s2=x2,s3=x3,s4=x4,s5=x5,s6=x6,s7=x7;
