    _mm_storeu_si128((__m128i*)w[8], x8); _mm_storeu_si128((__m128i*)w[9], x9);
    _mm_storeu_si128((__m128i*)w[10], x10); _mm_storeu_si128((__m128i*)w[11], x11);
    _mm_storeu_si128((__m128i*)w[12], x12); _mm_storeu_si128((__m128i*)w[13], x13);
