#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);

#define NTH 6
#define NMSG 8
#define MSGSZ (40000ull*1024ull)

typedef struct {
    unsigned char *in, *out;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
    int id;
} job;

static job jobs[NTH];
static pthread_t th[NTH];
static pthread_mutex_t mu[NTH];
static pthread_cond_t cv[NTH], done[NTH];
static int cmd[NTH];
static int finished[NTH];

static void *fn(void *arg) {
    int id = (int)(intptr_t)arg;
    pthread_mutex_lock(&mu[id]);
    for (;;) {
        while (cmd[id]==0) pthread_cond_wait(&cv[id], &mu[id]);
        if (cmd[id]==2) { pthread_mutex_unlock(&mu[id]); return NULL; }
        pthread_mutex_unlock(&mu[id]);
        ChaCha20_ctr32(jobs[id].out, jobs[id].in, jobs[id].len, jobs[id].key, jobs[id].counter);
        pthread_mutex_lock(&mu[id]);
        cmd[id]=0; finished[id]=1; pthread_cond_signal(&done[id]);
    }
}

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

int main() {
    for (int i=0;i<NTH;i++) {
        pthread_mutex_init(&mu[i], NULL);
        pthread_cond_init(&cv[i], NULL);
        pthread_cond_init(&done[i], NULL);
        cmd[i]=0; finished[i]=1;
        pthread_create(&th[i], NULL, fn, (void*)(intptr_t)i);
        jobs[i].in = aligned_alloc(64, MSGSZ);
